mapper.select:

where a.shop_code = #{shopCode}

  and a.accountcode = #{accountCode}


  and a.accountname like concat('%', #{accountName}, '%')


  and a.bankname like concat('%', #{bankName}, '%')


  and a.isactive = #{isActive}

order by a.isactive desc, a.accountcode

